from erlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
b = Board('ER_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}.tbl{display:grid;gap:8px 12px;font-size:13px;line-height:20px;color:#334155;align-items:center}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
def sw(t, k):
    bg, hd = TONES[k]
    return f'<span style="display:inline-block;width:56px;height:20px;border:2px solid #0F172A;border-radius:6px;background:{hd}"></span><b>{t}</b>'
tones = [('Customer, user', 'blue'), ('Order, document', 'violet'), ('Payment, money', 'amber'), ('Restaurant, catalogue', 'green'), ('Courier, delivery', 'teal'), ('Junction, lookup', 'gray')]
trow = ''.join(f'{sw(t, k)}' for t, k in tones)
card_rows = [('one', 'Exactly one'), ('zero_one', 'Zero or one'), ('many', 'One or many'), ('zero_many', 'Zero or many')]
cards = [
 card('Tables', ul('A table is a box with a header and rows. The name is a singular noun in PascalCase: <i>Order</i>, <i>OrderItem</i>.', 'Width 240 px, at least 200. Row 28 px. Header 40 px plain, 64 px illustrated.', 'The header tint says which domain the table belongs to. The icon is the same as the actor in a flowchart or sequence.', 'The diagram shows the keys and the columns that explain the relationships, not the whole schema.')),
 card('Columns and keys', ul('Names are snake_case. Order: primary key, foreign keys, then the rest.', 'Badges <b>PK</b>, <b>FK</b>, <b>UQ</b> on the left. A column may carry two (PK FK). The primary key name is bold.', 'The type is mono, grey, on the right, in generic names: uuid, text, int, decimal, bool, timestamp. The author may use a dialect instead.', 'A <b>?</b> after the type means the column can be empty.')),
 card('Cardinality', f'<div class="tbl" style="grid-template-columns:90px 1fr 1fr">' + ''.join(f'<span class="mono">{k}</span><b>{n}</b><span></span>' for k, n in card_rows) + '</div>' + ul('Crow\'s foot. The mark sits against the table it describes and reads as: each table at the other end relates to this many.', 'Every line has two marks. Marks are 28 px long and never cover a badge.')),
 card('Relationship lines', ul('<b>Solid ink:</b> a foreign key the database enforces. <b>Dashed slate:</b> a logical link with no constraint, for example to another service.', 'A line leaves the side of the foreign key row. When two tables are stacked, it runs straight between their edges.', 'Routes are orthogonal, with at most two bends. Crossing lines never join: there is no junction dot.', 'A verb on a pill names the link: <i>places</i>, <i>contains</i>. Active voice, read from the one side.')),
 card('Many to many', ul('Never drawn as one line. Add a junction table with two foreign keys that together are the primary key.', 'The junction table is grey unless it carries data of its own, such as a grade or a quantity. Then it gets a domain tint and a real name: <i>Enrollment</i>, <i>OrderItem</i>.', 'Both lines are one to zero-or-many, drawn from the outer tables.')),
 card('Layout', ul('Parents sit above or to the left of their children. The table the story is about is in the middle.', 'Columns 240 px wide with 160 px between them. Rows at least 110 px apart.', 'About ten tables per page. Longer: split by domain, and repeat a table in grey where two pages meet.', 'Keep the lines short. Put the most connected table where it touches the most neighbours.')),
 card('Colour by domain', f'<div style="display:grid;grid-template-columns:60px 1fr;gap:10px 14px;align-items:center;font-size:13px;color:#334155">{trow}</div>' + ul('The same tints as the flowchart lanes. Colour groups, it never carries a meaning on its own.', 'Optional dashed tinted frame with a pill label per domain, as in a screen flow. Not used in the examples yet.')),
 card('Animation', ul('One animated line: blue, thick, fast. It marks the path a typical query follows, for example Customer to Order to OrderItem.', 'Everything else is static. A second animated line cancels the effect.', 'Off when the viewer prefers reduced motion. In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('Two styles', ul('<b>Plain:</b> flat 18 px icon in a 40 px header. Default; for documentation and review.', '<b>Illustrated:</b> a name pill and a 52 px icon from the detailed set in a 64 px header. For readers outside the team.', 'Rows, keys, lines and marks are the same, so a diagram changes style without changing layout, apart from the 24 px of header height.')),
 card('Names and types', ul('Table names are singular. Foreign keys are named after what they point to, with <span class="mono">_id</span>: <span class="mono">customer_id</span>.', 'Keep a name the same in every diagram of one system, in flowcharts and sequences too.', 'Lengths, defaults and indexes are not drawn. Put them in a note or in the schema itself.')),
 card('Reading it with other diagrams', ul('A table can appear in a flowchart as a database step, and in a sequence as the Database participant. Same name, same green tint.', 'Not decided yet: marking which tables a sequence message touches.')),
 card('What a plugin can rely on', ul('A table is: id, name, icon, tone and a list of columns. A column is: name, type and flags (pk, fk, uq, null).', 'A relationship is: from table and column, to table and column, the cardinality at each end, optional label, style (solid or logical) and a main flag.', 'Placement comes from grid cells (column, row). The plugin spaces cells, picks the side a line leaves from, and routes it.', 'Many to many is stored as two relationships and a junction table.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">ER diagram · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions every ER diagram follows, and that a plugin can rely on. Notation shows marks, keys and lines, Patterns the common relationship shapes, and the examples show them together.</div></div>{grid}</div>')
print(save(b))
